#include "inventory_session_service.h"
#include "inventory_process_recovery.h"
#include "coin_pending_guard.h"
#include "house_inventory_transition.h"
#include "../database.h"
#include <openssl/rand.h>
#include <algorithm>
#include <stdexcept>
#include <type_traits>
namespace Housing::InventorySessions {namespace {
struct Failure{Error error;};
MySQLRequestResult Q(Database& db,const std::string& sql){auto r=db.QueryDatabase(sql,false);if(!r.Success())throw Failure{Error::DatabaseFailure};return r;}
struct Tx{Database& db;bool active=true;explicit Tx(Database& d):db(d){Q(db,"START TRANSACTION");}~Tx(){if(active)try{db.QueryDatabase(std::string("ROLLBACK"),false);}catch(...) {}}void Commit(){try{auto r=db.QueryDatabase(std::string("COMMIT"),false);if(!r.Success())throw Failure{Error::CommitUncertain};active=false;}catch(...){throw Failure{Error::CommitUncertain};}}};
bool Key(const std::string& s){if(s.empty()||s.size()>96)return false;for(auto c:s)if(!((c>='a'&&c<='z')||(c>='A'&&c<='Z')||(c>='0'&&c<='9')||c=='-'||c=='_'||c==':'||c=='.'))return false;return true;}
bool Shape(AuthenticatedPurchaser a,const Owner& o){return a.character_id&&a.account_id&&o.zone_id&&Key(o.process_key)&&Key(o.client_key);}
std::string Quote(Database& d,const std::string& s){return "'"+d.Escape(s)+"'";}
std::string Hex(const std::array<uint8_t,32>& token){std::string s;const char* h="0123456789abcdef";for(auto c:token){s+=h[c>>4];s+=h[c&15];}return s;}
std::array<uint8_t,32> Token(const char* p){if(!p||std::string(p).size()!=64)throw Failure{Error::DatabaseFailure};auto n=[](char c)->uint8_t{if(c>='0'&&c<='9')return uint8_t(c-'0');if(c>='A'&&c<='F')return uint8_t(c-'A'+10);if(c>='a'&&c<='f')return uint8_t(c-'a'+10);throw Failure{Error::DatabaseFailure};};std::array<uint8_t,32> t;for(size_t i=0;i<32;i++)t[i]=uint8_t(n(p[2*i])*16+n(p[2*i+1]));return t;}
void Verify(Database& d){auto r=Q(d,"SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND engine='InnoDB' AND table_name IN ('housing_inventory_sessions','housing_inventory_session_history','character_data','account','inventory')");if(r.RowCount()!=1||std::stoul(r.begin()[0])!=5)throw Failure{Error::DatabaseFailure};}
void Actor(Database& d,AuthenticatedPurchaser a){auto r=Q(d,"SELECT account_id,deleted_at FROM character_data WHERE id="+std::to_string(a.character_id)+" FOR UPDATE");if(r.RowCount()!=1||r.begin()[1]||std::stoul(r.begin()[0])!=a.account_id)throw Failure{Error::Unauthorized};auto account=Q(d,"SELECT id FROM account WHERE id="+std::to_string(a.account_id)+" FOR UPDATE");if(account.RowCount()!=1)throw Failure{Error::Unauthorized};}
void HousePending(Database& db,uint32_t character) {
 const auto state=HouseInventory::InspectPending(db,character,true);
 if(state!=HouseInventory::PendingState::Clear)
  throw Failure{state==HouseInventory::PendingState::Pending?Error::Busy:Error::DatabaseFailure};
}
std::string Columns(bool history){return "account_id,epoch,HEX(token),process_key,client_key,zone_id,instance_id,"+std::string(history?"released":"active");}
Lease Read(MySQLRequestRow r,uint32_t character,bool history){Lease l;l.actor={character,uint32_t(std::stoul(r[0]))};l.epoch=std::stoull(r[1]);l.token=Token(r[2]);l.owner={r[3],r[4],uint32_t(std::stoul(r[5])),uint16_t(std::stoul(r[6]))};auto state=std::stoul(r[7]);if(state>1||!l.epoch||!Shape(l.actor,l.owner))throw Failure{Error::DatabaseFailure};l.active=history?!state:bool(state);return l;}
bool Same(const Lease& a,const Lease& b){return a.actor.character_id==b.actor.character_id&&a.actor.account_id==b.actor.account_id&&a.epoch==b.epoch&&a.token==b.token&&a.owner.process_key==b.owner.process_key&&a.owner.client_key==b.owner.client_key&&a.owner.zone_id==b.owner.zone_id&&a.owner.instance_id==b.owner.instance_id;}
bool SameOwner(const Lease& l,AuthenticatedPurchaser a,const Owner& o){return l.actor.character_id==a.character_id&&l.actor.account_id==a.account_id&&l.owner.process_key==o.process_key&&l.owner.client_key==o.client_key&&l.owner.zone_id==o.zone_id&&l.owner.instance_id==o.instance_id;}
std::string Fields(const Lease& l,Database& db){return std::to_string(l.actor.character_id)+","+std::to_string(l.actor.account_id)+","+std::to_string(l.epoch)+",x'"+Hex(l.token)+"',"+Quote(db,l.owner.process_key)+","+Quote(db,l.owner.client_key)+","+std::to_string(l.owner.zone_id)+","+std::to_string(l.owner.instance_id);}
template<class T,class F>Result<T> Run(Database& db,F body){try{Tx tx(db);Verify(db);auto v=body();static_assert(std::is_nothrow_move_constructible_v<Result<T>>);Result<T> out{std::move(v),Error::None};tx.Commit();return out;}catch(const Failure& f){return {{},f.error};}catch(...){return {{},Error::DatabaseFailure};}}
}
Service::Service(std::unique_ptr<Database> db,bool enabled,bool supervised):database_(std::move(db)),enabled_(enabled),require_supervised_process_(supervised){}Service::~Service()=default;
Result<Lease> Service::Claim(AuthenticatedPurchaser a,const Owner& owner){std::lock_guard<std::mutex> lock(mutex_);if(!enabled_)return {{},Error::Disabled};if(!Shape(a,owner))return {{},Error::InvalidArgument};if(!database_||database_->GetStatus()!=DBcore::Connected)return {{},Error::DatabaseFailure};return Run<Lease>(*database_,[&]{auto& db=*database_;Actor(db,a);auto coin=CoinPending::Inspect(db,a.character_id,true);if(coin!=CoinPending::State::Clear)throw Failure{coin==CoinPending::State::Pending?Error::Busy:Error::DatabaseFailure};HousePending(db,a.character_id);if(require_supervised_process_&&!InventoryRecovery::RegisteredLiveProcess(db,owner.process_key))throw Failure{Error::Unauthorized};auto rows=Q(db,"SELECT "+Columns(false)+" FROM housing_inventory_sessions WHERE character_id="+std::to_string(a.character_id)+" FOR UPDATE");auto history=Q(db,"SELECT "+Columns(true)+" FROM housing_inventory_session_history WHERE character_id="+std::to_string(a.character_id)+" AND process_key="+Quote(db,owner.process_key)+" AND client_key="+Quote(db,owner.client_key)+" FOR UPDATE");uint64_t epoch=1;
 if(history.RowCount()){if(history.RowCount()!=1)throw Failure{Error::DatabaseFailure};auto old=Read(history.begin(),a.character_id,true);if(!SameOwner(old,a,owner))throw Failure{Error::Stale};if(!old.active)throw Failure{Error::AlreadyReleased};if(rows.RowCount()!=1)throw Failure{Error::DatabaseFailure};auto current=Read(rows.begin(),a.character_id,false);if(!current.active||!Same(old,current))throw Failure{Error::DatabaseFailure};return current;}
 if(rows.RowCount()){auto old=Read(rows.begin(),a.character_id,false);if(old.active)throw Failure{Error::Busy};if(old.epoch==UINT64_MAX)throw Failure{Error::DatabaseFailure};epoch=old.epoch+1;}
 Lease l{a,owner,epoch,{},true};if(RAND_bytes(l.token.data(),32)!=1)throw Failure{Error::DatabaseFailure};auto fields=Fields(l,db);auto historyInsert=Q(db,"INSERT INTO housing_inventory_session_history(character_id,account_id,epoch,token,process_key,client_key,zone_id,instance_id,released) VALUES ("+fields+",0)");if(historyInsert.RowsAffected()!=1)throw Failure{Error::DatabaseFailure};Q(db,"INSERT INTO housing_inventory_sessions(character_id,account_id,epoch,token,process_key,client_key,zone_id,instance_id,active) VALUES ("+fields+",1) ON DUPLICATE KEY UPDATE account_id=VALUES(account_id),epoch=VALUES(epoch),token=VALUES(token),process_key=VALUES(process_key),client_key=VALUES(client_key),zone_id=VALUES(zone_id),instance_id=VALUES(instance_id),active=1");return l;});}
Result<bool> Service::InspectHeld(const Lease& l){std::lock_guard<std::mutex> lock(mutex_);if(!enabled_)return {{},Error::Disabled};if(!Shape(l.actor,l.owner)||!l.epoch)return {{},Error::InvalidArgument};if(!database_||database_->GetStatus()!=DBcore::Connected)return {{},Error::DatabaseFailure};return Run<bool>(*database_,[&]{auto& db=*database_;Actor(db,l.actor);auto r=Q(db,"SELECT "+Columns(false)+" FROM housing_inventory_sessions WHERE character_id="+std::to_string(l.actor.character_id)+" FOR UPDATE");if(r.RowCount()!=1)throw Failure{Error::Stale};auto current=Read(r.begin(),l.actor.character_id,false);if(!Same(l,current))throw Failure{Error::Stale};return current.active;});}
Result<bool> Service::Release(const Lease& l){std::lock_guard<std::mutex> lock(mutex_);if(!enabled_)return {{},Error::Disabled};if(!Shape(l.actor,l.owner)||!l.epoch)return {{},Error::InvalidArgument};if(!database_||database_->GetStatus()!=DBcore::Connected)return {{},Error::DatabaseFailure};return Run<bool>(*database_,[&]{auto& db=*database_;auto rows=Q(db,"SELECT "+Columns(false)+" FROM housing_inventory_sessions WHERE character_id="+std::to_string(l.actor.character_id)+" FOR UPDATE");auto history=Q(db,"SELECT "+Columns(true)+" FROM housing_inventory_session_history WHERE character_id="+std::to_string(l.actor.character_id)+" AND epoch="+std::to_string(l.epoch)+" FOR UPDATE");if(history.RowCount()!=1)throw Failure{Error::Stale};auto old=Read(history.begin(),l.actor.character_id,true);if(!Same(old,l))throw Failure{Error::Stale};if(!old.active)return true;if(rows.RowCount()!=1)throw Failure{Error::Stale};auto current=Read(rows.begin(),l.actor.character_id,false);if(!current.active||!Same(current,l))throw Failure{Error::Stale};auto coin=CoinPending::Inspect(db,l.actor.character_id,true);if(coin!=CoinPending::State::Clear)throw Failure{coin==CoinPending::State::Pending?Error::Busy:Error::DatabaseFailure};HousePending(db,l.actor.character_id);auto released=Q(db,"UPDATE housing_inventory_session_history SET released=1 WHERE character_id="+std::to_string(l.actor.character_id)+" AND epoch="+std::to_string(l.epoch)+" AND released=0");auto inactive=Q(db,"UPDATE housing_inventory_sessions SET active=0 WHERE character_id="+std::to_string(l.actor.character_id)+" AND epoch="+std::to_string(l.epoch)+" AND active=1");if(released.RowsAffected()!=1||inactive.RowsAffected()!=1)throw Failure{Error::DatabaseFailure};return true;});}
Result<bool> Service::ResolveReleased(const Lease& l){std::lock_guard<std::mutex> lock(mutex_);if(!enabled_)return {{},Error::Disabled};if(!Shape(l.actor,l.owner)||!l.epoch)return {{},Error::InvalidArgument};if(!database_||database_->GetStatus()!=DBcore::Connected)return {{},Error::DatabaseFailure};return Run<bool>(*database_,[&]{auto& db=*database_;auto r=Q(db,"SELECT "+Columns(true)+" FROM housing_inventory_session_history WHERE character_id="+std::to_string(l.actor.character_id)+" AND epoch="+std::to_string(l.epoch)+" FOR UPDATE");if(r.RowCount()!=1)throw Failure{Error::Stale};auto old=Read(r.begin(),l.actor.character_id,true);if(!Same(old,l))throw Failure{Error::Stale};return !old.active;});}
}
